{"content": "1|export interface BinaryMethod {
2|  plugin_id: "threetched";
3|  method: string;
4|  path: string;
5|  declaration: {
6|    name: string;
7|    args: Record<string, unknown>;
8|    returns: Record<string, unknown>;
9|    side_effect: string;
10|    idempotent: boolean;
11|    required_capability: string;
12|    subid: string;
13|    usage?: string;
14|  };
15|}
16|
17|/** Parse fresh declarations obtained through this caller's mounted FUSE view. */
18|export function binaryMethods(value: unknown): BinaryMethod[] {
19|  if (!value || typeof value !== "object" || !Array.isArray((value as { methods?: unknown }).methods)) {
20|    throw new Error("The mounted threetched catalog is invalid.");
21|  }
22|  const methods = (value as { methods: unknown[] }).methods;
23|  if (!methods.length || methods.some((entry) => {
24|    if (!entry || typeof entry !== "object" || Array.isArray(entry)) return true;
25|    const method = entry as Partial<BinaryMethod>;
26|    const declaration = method.declaration;
27|    const capability = declaration?.required_capability;
28|    // Keep the sealed capability opaque: validate its namespace and matching subid,
29|    // never infer a grant from the command name. The mount owns admission.
30|    // (?![\s\S]) requires the actual end of input, not a boundary before a line terminator.
31|    return method.plugin_id !== "threetched" || typeof method.method !== "string" ||
32|      !/^[a-zA-Z0-9_-]+(?:\.[a-zA-Z0-9_-]+)*(?![\s\S])/.test(method.method) ||
33|      method.path !== `plugins/threetched/operations/${method.method}/call` ||
34|      !declaration || typeof declaration !== "object" || Array.isArray(declaration) ||
35|      declaration.name !== method.method ||
36|      typeof capability !== "string" || !/^cap\.software\.threetched\.call\.c[0-9a-f]{64}@v1(?![\s\S])/.test(capability) ||
37|      declaration.subid !== `mut.${capability.slice(4)}` ||
38|      typeof declaration.side_effect !== "string" || !declaration.side_effect ||
39|      typeof declaration.idempotent !== "boolean" ||
40|      !declaration.args || typeof declaration.args !== "object" || Array.isArray(declaration.args) ||
41|      !declaration.returns || typeof declaration.returns !== "object" || Array.isArray(declaration.returns);
42|  })) throw new Error("The mounted threetched catalog is invalid.");
43|  return methods as BinaryMethod[];
