{"content": "1|import type { DoorClient } from "../grpc/door";
2|import type { RouteSelection } from "./chat-adapter";
3|import type { CatalogModel } from "./model-catalog";
4|import type { Elevate } from "./elevation";
5|import { assertInferenceEndpoint, inferenceEndpointMatches, nativeProfilePath, readDedicatedRoute, readRouterValue, validateDedicatedRoute, verifiedNativeUri } from "./native-routing";
6|
7|const TCHED_ROUTER = "tched_router";
8|const WRITE = "cap.software.tched-router.router.write@v1";
9|export const CONTROL_PLANE_PROVIDER_PATH = "agents.control_plane.model_provider";
10|
11|export type ControlPlaneModelAccess = "self" | "admin";
12|
13|/** The server checks canonical identity, current $ROOT, mode and exact grant.
14| * Selected UI mode and local transport flags are never identity evidence. */
15|export async function controlPlaneModelAccess(client: DoorClient): Promise<ControlPlaneModelAccess> {
16|  const { result } = await client.call<{ can_apply?: unknown }>(
17|    TCHED_ROUTER, "get_own_agent_route_access", {}, "cap.software.tched-router.router.read@v1",
18|  );
19|  if (typeof result.can_apply !== "boolean") throw new Error("The door returned invalid own-model access. Refresh before applying.");
20|  return result.can_apply ? "self" : "admin";
21|}
22|
23|export class ControlPlaneMutationUnconfirmedError extends Error {
24|  constructor(cause: unknown) {
25|    super(`The model change could not be confirmed: ${cause instanceof Error ? cause.message : "door response unavailable"}. Refresh before retrying.`);
26|    this.name = "ControlPlaneMutationUnconfirmedError";
27|  }
28|}
29|
30|/** Read the actual dedicated agent route, then resolve it to a provider key. */
31|export async function currentControlPlaneModel(client: DoorClient, models: CatalogModel[], own?: boolean): Promise<RouteSelection> {
32|  const { reference, modelId, uri } = await readDedicatedRoute(client, "control_plane", own);
33|  const matches = models.filter((model) => model.available && model.model_id === modelId && model.control_plane_profile === reference && inferenceEndpointMatches(uri, model.inference_url_prefix));
34|  // Unmapped native selections remain visible as observed, never guessed.
35|  return { providerId: matches.length === 1 ? matches[0].provider_id : reference, modelId };
36|}
37|
38|/**
39| * Every mode uses the same provider-keyed Cozo catalog. The configured chatbot
40| * uses its bounded own-model operation without elevation; other identities keep
41| * the protected administration path. New methods require a matching reseal.
42| */
43|export async function setControlPlaneModel(
44|  client: DoorClient,
45|  selection: RouteSelection,
46|  models: CatalogModel[],
