{"content": "1|import type { DoorClient } from "../grpc/door";
2|
3|const ROUTER_READ = "cap.software.tched-router.router.read@v1";
4|const CATALOG_BINDING_READ = "cap.software.tched-router.model.binding.read@v1";
5|const NATIVE_PROVIDER_REF = /^[a-z][a-z0-9_-]*\.[a-z][a-z0-9_-]*$/;
6|
7|export interface ResolvedCatalogBinding {
8|  providerId: string;
9|  modelId: string;
10|  reference: string;
11|  model: string;
12|  uri: string;
13|  oauth: boolean;
14|  catalogRevision: number;
15|}
16|
17|export function nativeProfilePath(reference: string, field: "model" | "uri"): string {
18|  if (!NATIVE_PROVIDER_REF.test(reference)) throw new Error("The catalog contains an invalid native routing binding; expected family.alias.");
19|  return `providers.models.${reference}.${field}`;
20|}
21|
22|export async function readRouterValue(client: DoorClient, path: string): Promise<string> {
23|  const { result } = await client.call<{ value?: string | null }>("tched_router", "config_get", { path }, ROUTER_READ);
24|  if (typeof result.value !== "string" || !result.value.trim()) throw new Error(`The router has no configured value for ${path}.`);
25|  return result.value;
26|}
27|
28|function endpoint(value: unknown, label: string): URL {
29|  if (typeof value !== "string" || !value || value.trim() !== value) throw new Error(`${label} must be an explicit credential-free HTTPS URL.`);
30|  let url: URL;
31|  try { url = new URL(value); } catch { throw new Error(`${label} must be an explicit credential-free HTTPS URL.`); }
32|  if (url.protocol !== "https:" || url.username || url.password || value.includes("?") || value.includes("#") || value.includes("\\") || /%(?:2f|5c)/i.test(url.pathname)) {
33|    throw new Error(`${label} must be a credential-free HTTPS URL without query, fragment or escaped path separators.`);
34|  }
35|  return url;
36|}
37|
38|/** Compare explicit endpoint authority, including a complete path segment boundary. */
39|export function assertInferenceEndpoint(uri: unknown, prefix: unknown): void {
40|  const allowed = endpoint(prefix, "The model's inference_url_prefix");
41|  const actual = endpoint(uri, "The native inference URI");
42|  const path = allowed.pathname.replace(/\/+$/, "") || "/";
43|  if (actual.origin !== allowed.origin || (path !== "/" && actual.pathname !== path && !actual.pathname.startsWith(`${path}/`))) {
44|    throw new Error("The native inference URI does not match the model's inference_url_prefix. Configure the intended subscription endpoint before Apply.");
45|  }
46|}
47|
48|export function inferenceEndpointMatches(uri: string, prefix: unknown): boolean {
49|  try { assertInferenceEndpoint(uri, prefix); return true; } catch { return false; }
50|}
51|
52|/** Read only the exact native profile; no family/provider/CP fallback. */
53|export async function verifiedNativeUri(client: DoorClient, reference: string, prefix: unknown): Promise<string> {
54|  endpoint(prefix, "The model's inference_url_prefix");
55|  const uri = await readRouterValue(client, nativeProfilePath(reference, "uri"));
56|  assertInferenceEndpoint(uri, prefix);
57|  return uri;
58|}
59|
60|/** Resolve one catalog model against the router's current native profile inventory. */
61|export async function resolveCatalogModelBinding(
62|  client: DoorClient,
63|  providerId: string,
64|  modelId: string,
65|  inferenceUrlPrefix: unknown,
66|): Promise<ResolvedCatalogBinding> {
67|  const { result } = await client.call<{
68|    provider_id?: unknown;
69|    model_id?: unknown;
70|    reference?: unknown;
71|    model?: unknown;
72|    uri?: unknown;
73|    oauth?: unknown;
74|    catalog_revision?: unknown;
75|  }>(
76|    "tched_router",
77|    "resolve_catalog_model_binding",
78|    { provider_id: providerId, model_id: modelId },
79|    CATALOG_BINDING_READ,
80|  );
81|  return validateCatalogBinding(result, providerId, modelId, inferenceUrlPrefix);
82|}
83|
84|/** Apply only the backend's private ordinary-route binding, with exact preflight readback. */
85|export async function applyCatalogModelBinding(
86|  client: DoorClient,
87|  providerId: string,
88|  modelId: string,
89|  inferenceUrlPrefix: unknown,
90|  expected?: ResolvedCatalogBinding,
91|): Promise<ResolvedCatalogBinding> {
92|  const { result } = await client.call<{
93|    provider_id?: unknown; model_id?: unknown; reference?: unknown; model?: unknown; uri?: unknown; oauth?: unknown; catalog_revision?: unknown;
94|  }>(
95|    "tched_router",
96|    "apply_catalog_model_binding",
97|    { provider_id: providerId, model_id: modelId },
98|    "cap.software.tched-router.catalog.selection.set@v1",
99|  );
100|  const applied = validateCatalogBinding(result, providerId, modelId, inferenceUrlPrefix);
101|  if (expected && (!sameCatalogModelBinding(expected, applied) || expected.catalogRevision !== applied.catalogRevision)) {
102|    throw new Error("Change outcome unknown; applied native route differs from its preflight catalog binding. Refresh before retrying.");
103|  }
104|  return applied;
105|}
106|
107|function validateCatalogBinding(
108|  result: { provider_id?: unknown; model_id?: unknown; reference?: unknown; model?: unknown; uri?: unknown; oauth?: unknown; catalog_revision?: unknown },
109|  providerId: string,
110|  modelId: string,
111|  inferenceUrlPrefix: unknown,
112|): ResolvedCatalogBinding {
113|  if (result.provider_id !== providerId || result.model_id !== modelId) throw new Error("The router resolved a different catalog provider or model. Refresh models before applying.");
114|  if (typeof result.reference !== "string") throw new Error("The router has no exact native profile binding for this catalog model.");
115|  nativeProfilePath(result.reference, "model");
116|  if (result.model !== modelId) throw new Error("The resolved native profile model differs from the selected catalog model.");
117|  if (result.oauth !== undefined && typeof result.oauth !== "boolean") throw new Error("The router returned invalid native authentication metadata.");
118|  const oauth = result.oauth === true;
119|  if (oauth) {
120|    if (!result.reference.startsWith("openai.") || result.uri !== "") throw new Error("The router returned an invalid subscription-native binding.");
121|  } else assertInferenceEndpoint(result.uri, inferenceUrlPrefix);
122|  if (!Number.isSafeInteger(result.catalog_revision) || (result.catalog_revision as number) < 0) throw new Error("The router returned an invalid catalog revision for the native binding.");
123|  return { providerId, modelId, reference: result.reference, model: result.model, uri: result.uri as string, oauth, catalogRevision: result.catalog_revision as number };
124|}
125|
126|/** Compare binding identity and endpoint while allowing unrelated catalog rows to refresh. */
127|export function sameCatalogModelBinding(left: ResolvedCatalogBinding, right: ResolvedCatalogBinding): boolean {
128|  return left.providerId === right.providerId &&
129|    left.modelId === right.modelId &&
130|    left.reference === right.reference &&
131|    left.model === right.model &&
132|    left.uri === right.uri && left.oauth === right.oauth;
133|}
134|
135|export function validateDedicatedRoute(
136|  result: { mode?: unknown; reference?: unknown; model?: unknown; uri?: unknown },
137|  role: "control_plane" | "accountability",
138|) {
139|  if (result.mode !== role) throw new Error("The door returned a different dedicated agent mode. Refresh again.");
140|  if (typeof result.reference !== "string") throw new Error("The dedicated agent has no configured native profile.");
141|  nativeProfilePath(result.reference, "model");
142|  if (typeof result.model !== "string" || !result.model.trim() || result.model.trim() !== result.model) throw new Error("The dedicated agent has no configured model.");
143|  endpoint(result.uri, "The native inference URI");
144|  return { reference: result.reference, modelId: result.model, uri: result.uri as string };
145|}
146|
147|export async function readDedicatedRoute(client: DoorClient, role: "control_plane" | "accountability", own = client.isBoundOracle) {
148|  if (own) {
149|    const { result } = await client.call<{ mode: string; reference: string; model: string; uri: string }>(
150|      "tched_router", "get_own_agent_route", {}, "cap.software.tched-router.agent.route.self.read@v1",
151|    );
152|    return validateDedicatedRoute(result, role);
153|  }
154|  const path = `agents.${role}.model_provider`;
155|  const reference = await readRouterValue(client, path);
156|  const [modelId, uri] = await Promise.all([
157|    readRouterValue(client, nativeProfilePath(reference, "model")),
158|    readRouterValue(client, nativeProfilePath(reference, "uri")),
159|  ]);
160|  const [confirmedModel, confirmedUri] = await Promise.all([
161|    readRouterValue(client, nativeProfilePath(reference, "model")),
162|    readRouterValue(client, nativeProfilePath(reference, "uri")),
163|  ]);
164|  if (await readRouterValue(client, path) !== reference || confirmedModel !== modelId || confirmedUri !== uri) throw new Error(`The ${role === "control_plane" ? "Control Plane" : "Accountability"} selection changed while reading. Refresh again.`);
165|  return { reference, modelId, uri };
166|}
