{"content": "1|import { DoorError, type DoorClient } from "../grpc/door";
2|import type { RouteSelection } from "./chat-adapter";
3|import type { CatalogModel, CatalogProvider } from "./model-catalog";
4|import { resolveCatalogModelBinding } from "./native-routing";
5|
6|const ROUTER_STATE_READ = "cap.software.3tched-router.state.read@v1";
7|
8|interface ObservedRouterState {
9|  selected_provider?: string;
10|  selected_model?: string;
11|}
12|
13|/** Native router family from a catalog provider row or model binding reference. */
14|export function nativeFamilyFromCatalog(
15|  provider: CatalogProvider,
16|  model?: CatalogModel,
17|): string | null {
18|  const reference = model?.native_provider_id ?? provider.native_provider_id;
19|  if (reference?.includes(".")) {
20|    const [family] = reference.split(".", 2);
21|    if (family) return family;
22|  }
23|  return provider.provider_id || null;
24|}
25|
26|/**
27| * Map authoritative D-Bus-projected router selection to one catalog row.
28| * Fails closed when the observation does not identify a unique catalog model.
29| */
30|export function mapObservedRouterToCatalog(
31|  observed: ObservedRouterState,
32|  providers: CatalogProvider[],
33|  models: CatalogModel[],
34|): RouteSelection | null {
35|  const family = observed.selected_provider?.trim();
36|  const modelId = observed.selected_model?.trim();
37|  if (!family || !modelId) return null;
38|
39|  const candidates = models.filter(
40|    (row) =>
41|      row.available &&
42|      row.model_id === modelId &&
43|      providers.some(
44|        (provider) =>
45|          provider.provider_id === row.provider_id &&
46|          provider.configured &&
47|          provider.enabled,
48|      ),
49|  );
50|  if (!candidates.length) return null;
51|
52|  const byFamily = candidates.filter((row) => {
53|    const provider = providers.find((entry) => entry.provider_id === row.provider_id);
54|    if (!provider) return false;
55|    const rowFamily = nativeFamilyFromCatalog(provider, row);
56|    return rowFamily === family || provider.provider_id === family;
57|  });
58|
59|  const matches = byFamily.length > 0 ? byFamily : candidates;
60|  if (matches.length !== 1) return null;
61|
62|  return { providerId: matches[0].provider_id, modelId: matches[0].model_id };
63|}
64|
65|/**
66| * Read committed router selection through the door (D-Bus-backed CallMethod)
67| * before falling back to catalog ordering for the picker UI.
68| */
69|export async function loadCommittedCatalogRoute(
70|  client: DoorClient,
71|  providers: CatalogProvider[],
72|  models: CatalogModel[],
73|): Promise<{ selection: RouteSelection; bindingConfirmed: boolean } | null> {
74|  let result: { state?: ObservedRouterState };
75|  try {
76|    ({ result } = await client.call<{ state?: ObservedRouterState }>(
77|      "tched_router",
78|      "GetState",
79|      {},
80|      ROUTER_STATE_READ,
81|    ));
82|  } catch (error) {
83|    // Catalog access does not grant global router-state access. Keep the
84|    // selection unknown and unapplied; selection/chat still require admission.
85|    if (error instanceof DoorError && error.code === "PERMISSION_DENIED") return null;
86|    throw error;
87|  }
88|  const selection = mapObservedRouterToCatalog(result.state ?? {}, providers, models);
89|  if (!selection) return null;
90|
91|  const model = models.find(
92|    (row) => row.provider_id === selection.providerId && row.model_id === selection.modelId,
93|  );
94|  if (!model?.inference_url_prefix) {
95|    return { selection, bindingConfirmed: false };
96|  }
97|
98|  try {
99|    const binding = await resolveCatalogModelBinding(
100|      client,
101|      selection.providerId,
102|      selection.modelId,
103|      model.inference_url_prefix,
104|    );
105|    return {
106|      selection,
107|      bindingConfirmed: binding.model === selection.modelId,
108|    };
109|  } catch {
110|    return { selection, bindingConfirmed: false };
111|  }
