2|import type { DoorClient } from "../grpc/door";
3|import { applicationProfile } from "../json-render/references/application-contract";
4|import { resolveApplicationValue, validateApplicationSpec } from "../json-render/references/application-validation";
5|
6|const operation = z.strictObject({
7|  method: z.string().min(1), call_path: z.string().min(1), metadata_path: z.string().min(1),
8|  currently_granted: z.boolean(),
9|});
10|const plugin = z.strictObject({
11|  plugin_id: z.string().min(1), object_hash: z.string().min(1), schema_hash: z.string().min(1),
12|  schema: z.record(z.string(), z.unknown()), operations: z.array(operation), state: z.literal("not_requested"),
13|});
14|const catalog = z.strictObject({ views: z.array(z.strictObject({
15|  view_id: z.string().min(1), source_catalog_hash: z.string().min(1),
16|  source_catalog_generation: z.number().int().nonnegative(), plugins: z.array(plugin),
17|})).length(2) });
18|export type MountedCatalog = z.infer<typeof catalog>;
19|const applicationPins = new WeakMap<object, string>();
20|export function applicationRendererPin(spec: object): string | undefined {
21|  return applicationPins.get(spec);
22|}
23|
24|export async function readMountedCatalog(client: DoorClient, pluginId?: string): Promise<MountedCatalog> {
25|  const { result } = await client.call<unknown>("tched_fs", "get_catalog", { plugin: pluginId ?? null },
26|    "cap.storage.3tchedfs.contract.read@v1");
27|  const parsed = catalog.parse(result);
28|  const seen = new Set<string>();
29|  for (const view of parsed.views) for (const entry of view.plugins) {
30|    if (seen.has(entry.plugin_id) || (pluginId !== undefined && entry.plugin_id !== pluginId))
31|      throw new Error("Mounted catalog has ambiguous plugin ownership.");
32|    seen.add(entry.plugin_id);
33|  }
34|  return parsed;
35|}
36|
37|function sameJson(left: unknown, right: unknown): boolean {
38|  if (left === right) return true;
39|  if (left === null || right === null || typeof left !== "object" || typeof right !== "object") return false;
40|  if (Array.isArray(left) || Array.isArray(right))
41|    return Array.isArray(left) && Array.isArray(right) && left.length === right.length && left.every((value, index) => sameJson(value, right[index]));
42|  const a = left as Record<string, unknown>, b = right as Record<string, unknown>;
43|  return Object.keys(a).length === Object.keys(b).length && Object.keys(a).every(key => Object.hasOwn(b, key) && sameJson(a[key], b[key]));
44|}
45|
46|/** Admit a generated or retained application against current caller-visible seals. */
47|export async function admitMountedApplication(client: DoorClient, value: unknown, rendererHash: string) {
48|  const current = await readMountedCatalog(client);
49|  const plugins = new Map(current.views.flatMap(view => view.plugins).map(entry => [entry.plugin_id, entry]));
50|  const renderer = plugins.get("json_render");
51|  const fields = z.record(z.string(), z.unknown()).parse(renderer?.schema.fields);
52|  const profile = z.object({ default: z.unknown() }).parse(fields.application_profile).default;
53|  if (!rendererHash || renderer?.schema_hash !== rendererHash || !sameJson(profile, applicationProfile))
54|    throw new Error("Application renderer is stale or differs from this UI bundle. Regenerate with the current renderer.");
55|  const spec = validateApplicationSpec(value);
56|  for (const [name, hash] of Object.entries(spec.target_contracts ?? {})) {
57|    if (plugins.get(name)?.schema_hash !== hash) throw new Error("Application target seal is stale. Regenerate the application.");
58|  }
59|  for (const element of Object.values(spec.elements)) for (const binding of Object.values(element.on ?? {})) {
60|    const action = z.object({ action: z.string(), params: z.unknown() }).parse(binding);
61|    if (action.action !== "invokePlugin") continue;
62|    const params = z.object({ plugin: z.string(), method: z.string(), capability: z.string(), arguments: z.record(z.string(), z.unknown()) })
63|      .parse(resolveApplicationValue(action.params, spec.state ?? {}));
64|    const target = plugins.get(params.plugin);
65|    const methods = z.record(z.string(), z.unknown()).parse(target?.schema.methods);
66|    const declaration = z.object({ required_capability: z.string(), args: z.record(z.string(), z.unknown()) }).parse(methods[params.method]);
67|    if (declaration.required_capability !== params.capability || !target?.operations.some(entry => entry.method === params.method && entry.currently_granted))
68|      throw new Error("Application action is no longer authorized. Regenerate the application.");
69|    z.fromJSONSchema(declaration.args).parse(params.arguments);
70|  }
71|  applicationPins.set(spec, rendererHash);
72|  return spec;
